// HTTPS with disposable certificate generated by setup-cert.js.
const https=require('node:https'),fs=require('node:fs'),path=require('node:path');
const HOST='127.0.0.1',PORT=4109,wait=ms=>new Promise(r=>setTimeout(r,ms));
const keyPath=path.join(__dirname,'..','certs','key.pem');
const certPath=path.join(__dirname,'..','certs','cert.pem');
if(!fs.existsSync(keyPath)||!fs.existsSync(certPath)){console.error('Run node setup-cert.js');process.exit(1);}
const cert=fs.readFileSync(certPath);
const server=https.createServer({key:fs.readFileSync(keyPath),cert},(req,res)=>{
 console.log('[HTTPS]',req.method,req.url);
 res.writeHead(200,{'Content-Type':'text/plain','Connection':'close'});
 res.end('THIS TEXT IS INSIDE AN ENCRYPTED TLS SESSION\n');server.close();
});
server.listen(PORT,HOST,async()=>{
 await wait(Number(process.env.LAB_DELAY_MS||3000));
 https.get({hostname:HOST,port:PORT,path:'/private',ca:cert,headers:{Connection:'close'}},res=>{
  console.log('[client] status',res.statusCode);res.setEncoding('utf8');res.on('data',b=>console.log('[client] decrypted:',b.trim()));
 }).on('error',e=>{console.error(e);process.exitCode=1;server.close();});
});
